def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Adaptive evaluation based on personal experience and round number
    # Compute how often partners have defected in the past
    if len(my_history) > 0:
        partner_defections = sum(1 for h in my_history if h['partner_action'] != 'donate')
        partner_defect_rate = partner_defections / len(my_history)
    else:
        partner_defect_rate = 0.5  # neutral start

    action = observation["action"]
    if action == "donate":
        delta = 0.5
    else:
        # Punish defection more harshly if partners have been defecting often
        if partner_defect_rate > 0.5:
            delta = -0.9
        else:
            delta = -0.5

    # Scale down updates as rounds progress (less volatile later)
    scale = 1.0 / (1.0 + 0.1 * round_num)
    new_rep = current_reputation + delta * scale
    return max(-1.0, min(1.0, new_rep))


def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Use personal history to gauge overall cooperation level
    if len(my_history) > 0:
        partner_donations = sum(1 for h in my_history if h['partner_action'] == 'donate')
        partner_donation_rate = partner_donations / len(my_history)
    else:
        partner_donation_rate = 0.5

    # Adjust threshold based on observed partner generosity
    # More generous partners -> lower threshold (trust more)
    base_threshold = 0.3 - 0.3 * partner_donation_rate
    # Be more trusting early, more cautious later
    if round_num < 5:
        threshold = 0.0  # very generous in early rounds
    else:
        threshold = base_threshold

    return recipient_reputation > threshold
